-- Runs against a disposable/local database or in a rolled-back hosted transaction.
-- No fixtures survive this script. Run as the migration administrator.
begin;
do $$
declare
 owner_a uuid=gen_random_uuid(); owner_b uuid=gen_random_uuid(); munshi uuid=gen_random_uuid();
 wa uuid; wb uuid; sid uuid; tank uuid; nozzle uuid; delivery uuid; shift uuid; account uuid; vehicle uuid; credential uuid; eid uuid; e2 uuid; e3 uuid; e4 uuid; e5 uuid;
 indent uuid; result jsonb; tracking_token text; failed boolean; amount numeric;
begin
 insert into auth.users(id,email,email_confirmed_at,aud,role) values(owner_a,owner_a||'@example.invalid',now(),'authenticated','authenticated'),(owner_b,owner_b||'@example.invalid',now(),'authenticated','authenticated'),(munshi,munshi||'@example.invalid',now(),'authenticated','authenticated');
 perform set_config('request.jwt.claim.sub',owner_a::text,true);
 execute 'set local role authenticated';
 wa=(public.command('join','{"name":"QA workspace A","person":"QA owner"}') ->>'id')::uuid;
 sid=(public.command('station','{"name":"QA station","omc":"QA","city":"Karachi"}')->>'id')::uuid;
 tank=(public.command('tank',jsonb_build_object('station_id',sid,'name','Petrol','grade','MS','capacity',50000,'dip',2000,'chart','[{"mm":0,"liters":0},{"mm":5000,"liters":50000}]'::jsonb))->>'id')::uuid;
 nozzle=(public.command('nozzle',jsonb_build_object('station_id',sid,'tank_id',tank,'name','N1','totalizer',1000))->>'id')::uuid;
 perform public.command('price',jsonb_build_object('station_id',sid,'grade','MS','price',300,'beta',0.00115,'margin',10,'effective_at',now(),'source','QA fixture'));
 perform public.command('invite',jsonb_build_object('station_id',sid,'email',munshi||'@example.invalid','name','QA Munshi'));
 shift=(public.command('open_shift',jsonb_build_object('station_id',sid,'name','QA shift'))->>'id')::uuid;
 failed=false;begin perform public.command('open_shift',jsonb_build_object('station_id',sid,'name','Duplicate'));exception when others then failed=true;end;assert failed,'Duplicate open shift was accepted';
 failed=false;begin perform public.command('nozzle',jsonb_build_object('station_id',sid,'tank_id',tank,'name','N2','totalizer',0));exception when others then failed=true;end;assert failed,'Equipment changed mid-shift';
 account=(public.command('account',jsonb_build_object('station_id',sid,'name','QA customer','credit_limit',50000))->>'id')::uuid;
 vehicle=(public.command('vehicle',jsonb_build_object('station_id',sid,'account_id',account,'registration','QA-1','grade','MS','max_liters',200))->>'id')::uuid;
 select token into credential from public.vehicles where id=vehicle;
 delivery=(public.command('delivery',jsonb_build_object('station_id',sid,'tank_id',tank,'reference',gen_random_uuid(),'vehicle','QA-2','depot','QA depot','invoice',10000,'loading_temp',38,'chambers','[[{"mm":0,"liters":0},{"mm":1000,"liters":10000}]]'::jsonb))->>'id')::uuid;
 tracking_token=public.tracking('create',jsonb_build_object('delivery_id',delivery,'depot_lat',24,'depot_lon',67,'station_lat',25,'station_lon',68))->>'token';
 perform set_config('request.jwt.claim.sub','',true);
 execute 'set local role anon';
 assert public.tracking('status',jsonb_build_object('token',tracking_token))->>'vehicle'='QA-2','Valid driver token rejected';
 perform public.tracking('ping',jsonb_build_object('token',tracking_token,'latitude',24.5,'longitude',67.5,'accuracy',15));
 failed=false;begin perform public.tracking('read',jsonb_build_object('delivery_id',delivery));exception when others then failed=true;end;assert failed,'Anonymous caller could read owner tracking data';
 failed=false;begin perform public.tracking('status',jsonb_build_object('token',repeat('a',64)));exception when others then failed=true;end;assert failed,'Invalid tracking token accepted';
 execute 'set local role authenticated';
 perform set_config('request.jwt.claim.sub',owner_b::text,true);
 wb=(public.command('join','{"name":"QA workspace B","person":"QA outsider"}')->>'id')::uuid;
 assert (select count(*) from public.tanks where id=tank)=0,'Cross-tenant RLS leak';
 failed=false;begin perform public.command('approve_delivery',jsonb_build_object('station_id',sid,'id',delivery));exception when others then failed=true;end;assert failed,'Cross-tenant write accepted';
 perform set_config('request.jwt.claim.sub',munshi::text,true);
 perform public.command('join','{}');
 result=public.dashboard();
 assert result->'member'->>'role'='munshi','Invitation did not assign Munshi';
 assert not (result ? 'prices') and not (result ? 'accounts'),'Kiosk financial data leak';
 assert not (result->'tanks'->0 ? 'chart') and not (result->'tanks'->0 ? 'stock'),'Kiosk calibration leak';
 assert (select count(*) from public.tanks)=0,'Munshi direct table read allowed';
 failed=false;begin perform public.command('approve_delivery',jsonb_build_object('station_id',sid,'id',delivery));exception when others then failed=true;end;assert failed,'Munshi could approve delivery';
 failed=false;begin update public.memberships set role='owner' where user_id=munshi;exception when others then failed=true;end;assert failed,'Munshi could escalate role';
 execute 'reset role';
 insert into public.evidence(workspace_id,station_id,uploaded_by,path,captured_at,sha256) values(wa,sid,munshi,'qa/'||gen_random_uuid(),now(),repeat('a',64)) returning id into eid;
 insert into public.evidence(workspace_id,station_id,uploaded_by,path,captured_at,sha256) values(wa,sid,munshi,'qa/'||gen_random_uuid(),now(),repeat('b',64)) returning id into e2;
 insert into public.evidence(workspace_id,station_id,uploaded_by,path,captured_at,sha256) values(wa,sid,munshi,'qa/'||gen_random_uuid(),now(),repeat('c',64)) returning id into e3;
 insert into public.evidence(workspace_id,station_id,uploaded_by,path,captured_at,sha256) values(wa,sid,munshi,'qa/'||gen_random_uuid(),now(),repeat('d',64)) returning id into e4;
 insert into public.evidence(workspace_id,station_id,uploaded_by,path,captured_at,sha256) values(wa,sid,munshi,'qa/'||gen_random_uuid(),now(),repeat('e',64)) returning id into e5;
 execute 'set local role authenticated';
 perform public.command('submit_delivery',jsonb_build_object('station_id',sid,'id',delivery,'arrival_temp',32,'dips','[990]'::jsonb,'evidence_id',eid));
 failed=false;begin perform public.command('submit_delivery',jsonb_build_object('station_id',sid,'id',delivery,'arrival_temp',32,'dips','[1000]'::jsonb,'evidence_id',eid));exception when others then failed=true;end;assert failed,'Submitted audit changed';
 failed=false;begin perform public.command('decant',jsonb_build_object('station_id',sid,'id',delivery));exception when others then failed=true;end;assert failed,'Unapproved decant accepted';
 perform set_config('request.jwt.claim.sub',owner_a::text,true);
 select claim into amount from public.deliveries where id=delivery;
 assert amount=9300,'Thermal claim was incorrectly calculated';
 indent=(public.ops_command('create',jsonb_build_object('station_id',sid,'kind','indent','title','QA procurement request','supplier','QA OMC','grade','MS','liters',10000,'assigned_to',munshi))->>'id')::uuid;
 perform public.ops_command('transition',jsonb_build_object('id',indent,'expected_status','requested','status','approved'));
 perform public.ops_command('transition',jsonb_build_object('id',indent,'expected_status','approved','status','dispatched','delivery_id',delivery));
 failed=false;begin perform public.ops_command('transition',jsonb_build_object('id',indent,'expected_status','dispatched','status','received'));exception when others then failed=true;end;assert failed,'Indent received before physical decant';

 perform public.command('approve_delivery',jsonb_build_object('station_id',sid,'id',delivery));
 perform set_config('request.jwt.claim.sub',munshi::text,true);
 perform public.command('decant',jsonb_build_object('station_id',sid,'id',delivery));
 perform set_config('request.jwt.claim.sub',owner_a::text,true);
 select stock into amount from public.tanks where id=tank;
 perform set_config('request.jwt.claim.sub',munshi::text,true);
 perform public.ops_command('transition',jsonb_build_object('id',indent,'expected_status','dispatched','status','received'));
 perform set_config('request.jwt.claim.sub',owner_a::text,true);
 assert (select stock from public.tanks where id=tank)=amount,'Indent receipt duplicated stock posting';
 perform set_config('request.jwt.claim.sub',munshi::text,true);
 assert (select status from public.station_work_items where id=indent)='received','Indent not received';
 failed=false;begin perform public.command('decant',jsonb_build_object('station_id',sid,'id',delivery));exception when others then failed=true;end;assert failed,'Duplicate decant accepted';
 perform public.command('parchi',jsonb_build_object('station_id',sid,'token',credential,'nozzle_id',nozzle,'liters',100,'evidence_id',e2,'request_id',gen_random_uuid()));
 failed=false;begin perform public.command('parchi',jsonb_build_object('station_id',sid,'token',credential,'nozzle_id',nozzle,'liters',100,'evidence_id',e3,'request_id',gen_random_uuid()));exception when others then failed=true;end;assert failed,'Credit limit exceeded';
 perform public.command('close_shift',jsonb_build_object('station_id',sid,'id',shift,'nozzles',jsonb_build_array(jsonb_build_object('id',nozzle,'closing',1200,'testing',0,'evidence_id',e4)),'tanks',jsonb_build_array(jsonb_build_object('id',tank,'dip',2970,'evidence_id',e5)),'cash',30000,'pos',0));
 perform set_config('request.jwt.claim.sub',owner_a::text,true);
 select ss.result into result from public.shifts ss where ss.id=shift;
 assert (result->>'revenue')::numeric=60000,'Nozzle revenue incorrect';
 assert (result->>'credit')::numeric=30000,'Credit was not linked to shift';
 assert (result->>'cash_variance')::numeric=0,'Cash reconciliation incorrect';
 assert (result->'tanks'->0->>'variance')::numeric=0,'Stock reconciliation incorrect';
 perform public.command('review_shift',jsonb_build_object('station_id',sid,'id',shift,'note','QA reviewed'));
 perform public.command('revoke',jsonb_build_object('id',munshi));
 perform set_config('request.jwt.claim.sub',munshi::text,true);
 assert public.dashboard()->'member'='null'::jsonb,'Revocation did not take effect';
 failed=false;begin perform public.command('join','{"name":"Bypass workspace"}');exception when others then failed=true;end;assert failed,'Revoked user regained access';
 execute 'reset role';
end $$;
select 'PASS: tenant isolation, kiosk projection, role escalation, immutable audit, approval gate, duplicate decant, credit limit, stock/cash reconciliation, revocation' as result;
rollback;
